record.field:
backend = model.env['sage.backend'].search([('active', '=', True), ('company_id', '=', model.env.company.id)], limit=1)
if backend:
    if backend.import_customers:
        model.enqueue(backend, 'import_customers')
    if backend.import_suppliers:
        model.enqueue(backend, 'import_suppliers')
    if backend.import_products:
        model.enqueue(backend, 'import_products')
    if backend.import_invoices:
        model.enqueue(backend, 'import_invoices')
